  function migrateAndLoadVoicePrefs() {
    let lang = (localStorage.getItem("agy_hub_voice_lang") || "ru").trim().toLowerCase();
    if (!["ru", "en", "auto"].includes(lang)) lang = "ru";

    let rawEngine = (localStorage.getItem("agy_hub_voice_engine") || "").trim().toLowerCase();
    let rawModel = (localStorage.getItem("agy_hub_voice_model") || "").trim().toLowerCase();

    if (!localStorage.getItem("agy_hub_voice_v55_migrated")) {
      const wasForcedWhisper = rawEngine === "whisper_only";
      if ((lang === "ru" || lang === "auto" || !lang) && !wasForcedWhisper && rawEngine !== "live" && rawEngine !== "groq") {
        rawEngine = "gigaam";
        if (!rawModel || rawModel === "small" || rawModel === "medium" || rawModel === "large-v3-turbo") {
          rawModel = "accurate";
        } else if (rawModel === "base" || rawModel === "tiny") {
          rawModel = "fast";
        }
      } else if (wasForcedWhisper) {
        rawEngine = "whisper";
      }
      if (rawModel === "small" || rawModel === "medium" || rawModel === "large-v3-turbo") {
        rawModel = "accurate";
      } else if (rawModel === "base" || rawModel === "tiny") {
        rawModel = "fast";
      }
      try {
        localStorage.setItem("agy_hub_voice_engine", rawEngine || "gigaam");
        localStorage.setItem("agy_hub_voice_model", rawModel || "accurate");
        localStorage.setItem("agy_hub_voice_v55_migrated", "1");
      } catch {}
    }

    if (rawEngine === "auto") rawEngine = "gigaam";
    if (rawEngine === "whisper_only") rawEngine = "whisper";
    if (!["gigaam", "whisper", "groq", "live"].includes(rawEngine)) rawEngine = "gigaam";

    if (rawModel === "small" || rawModel === "medium") rawModel = "accurate";
    if (rawModel === "base" || rawModel === "tiny") rawModel = "fast";
    if (!["accurate", "fast"].includes(rawModel)) rawModel = "accurate";

    return { engine: rawEngine, model: rawModel, lang };
  }

