  // --- Sibling Project Chats Discovery (used by 🚀 В Код & @чат) ---
  function getKnownProjectChats(projName) {
    if (!projName) return [];
    const pLow = String(projName).toLowerCase();
    const map = new Map();
    const cached = state.projectChatsCache.get(pLow);
    if (cached && Array.isArray(cached.chats)) {
      for (const c of cached.chats) {
        if (c && c.id) map.set(c.id, c);
      }
    }
    for (const c of state.chats || []) {
      if (c && c.id && c.kind === "project" && (c.project_name || "").toLowerCase() === pLow) {
        map.set(c.id, Object.assign({}, map.get(c.id) || {}, c));
      }
    }
    for (const c of state.recentAllChats || []) {
      if (c && c.id && c.kind === "project" && (c.project_name || "").toLowerCase() === pLow) {
        if (!map.has(c.id)) map.set(c.id, c);
      }
    }
    for (const t of state.openTabs || []) {
      if (t && t.type === "chat" && t.id && (t.project_name || "").toLowerCase() === pLow) {
        if (!map.has(t.id)) {
          map.set(t.id, {
            id: t.id,
            kind: "project",
            project_name: t.project_name,
            title: t.title || "Диалог",
            icon: t.icon || "",
            access_mode: "read_only",
            is_generating: Boolean(t.is_generating || state.generatingChats.has(t.id)),
            bookmark_count: 0,
            updated_at: "",
          });
        }
      }
    }
    return [...map.values()].sort((a, b) =>
      String(b.updated_at || "").localeCompare(String(a.updated_at || ""))
    );
  }

  async function refreshProjectSiblingChats(projName) {
    if (!projName) return [];
    const pLow = String(projName).toLowerCase();
    const cached = state.projectChatsCache.get(pLow);
    if (cached && Date.now() - cached.ts < 8000 && Array.isArray(cached.chats)) {
      return cached.chats;
    }
    try {
      const data = await apiFetch(
        `/api/chats?kind=project&project_name=${encodeURIComponent(projName)}`
      );
      const list = Array.isArray(data && data.chats) ? data.chats : [];
      state.projectChatsCache.set(pLow, { ts: Date.now(), chats: list });
      return list;
    } catch {
      return getKnownProjectChats(projName);
    }
  }

  // --- 🚀 В Код (1-Click Plan -> Code Handoff) ---
  function resolvePreferredHandoffAccessMode(projName) {
    const projObj = findProjectMetaByName(projName);
    if (projObj && projObj.execution_mode === "sandbox_files") {
      const maxM = isAdminUser()
        ? "host_full"
        : (state.currentUser && state.currentUser.max_access_mode) || "write_files";
      return maxM === "read_only" ? "read_only" : "write_files";
    }
    if (isAdminUser()) {
      if (isProjectDockerContour(projName) && !isDockerSandboxReady()) {
        return "write_files";
      }
      return "full_access";
    }
    const maxMode = (state.currentUser && state.currentUser.max_access_mode) || "write_files";
    if (maxMode === "host_full") {
      if (isProjectDockerContour(projName) && !isDockerSandboxReady()) {
        return "write_files";
      }
      return "full_access";
    }
    if (maxMode === "docker_full") {
      return isDockerSandboxReady() ? "full_access" : "write_files";
    }
    if (maxMode === "read_only") return "read_only";
    return "write_files";
  }

  function getHandoffModeDisplayLabel(projName, mode) {
    if (mode === "full_access") {
      const isDockerCtx = isProjectDockerContour(projName);
      return isDockerCtx ? "🐳 Терминал" : "Терминал";
    }
    if (mode === "write_files") {
      return "Код";
    }
    return "План";
  }

