    if (els.chatActiveProcessesBar) {
      els.chatActiveProcessesBar.addEventListener("click", async (e) => {
        const btn = e.target.closest("[data-cap-act]");
        if (!btn) return;
        e.preventDefault();
        e.stopPropagation();
        const act = String(btn.dataset.capAct || "");
        const pName =
          String(btn.dataset.capProj || "").trim() || getActiveProjectContextName();
        const sName = String(btn.dataset.capName || "").trim();
        if (act === "open-all") {
          openHostServicesModal(pName, pName ? "project" : "all");
          return;
        }
        if (act === "clear-crashes") {
          if (pName) {
            await dismissAllProjectCrashes(pName);
          }
          return;
        }
        if (!pName || !sName) return;
        if (act === "jump") {
          const msgId = String(btn.dataset.capMsg || "").trim();
          if (msgId) {
            jumpToOutlineTarget({ msgId });
          } else {
            await openHostServicesModal(pName, "project");
            await openHostServiceLogs(sName, pName);
          }
        } else if (act === "logs") {
          await openHostServicesModal(pName, "project");
          await openHostServiceLogs(sName, pName);
        } else if (act === "stop") {
          await runHostServiceAction(sName, "stop", {}, pName);
        } else if (act === "ai-fix") {
          await sendProcessErrorToChat(pName, sName);
        } else if (act === "ack") {
          state.hostServices.dismissedCrashKeys.add(
            `${pName.toLowerCase()}::${sName.toLowerCase()}`
          );
          const item = findCachedProcessItem(pName, sName);
          if (item) item.crash_unseen = false;
          const pObj = findProjectMetaByName(pName);
          if (pObj && pObj.processes_summary) {
            const curUnseen = Number(
              pObj.processes_summary.unseen_crash_count ??
                pObj.processes_summary.crashed_count ??
                0
            );
            pObj.processes_summary.unseen_crash_count = Math.max(0, curUnseen - 1);
          }
          syncSecurityModeUI();
          renderChatActiveProcessesBar();
          await runHostServiceAction(sName, "ack", {}, pName, { silentToast: true });
        }
      });
    }
