    if (els.sharedProjectsAdminList) {
      els.sharedProjectsAdminList.addEventListener("change", (e) => {
        const card = e.target.closest("[data-sp-card]");
        if (!card) return;
        const spId = card.dataset.spCard || "";
        if (!spId) return;
        const modeSel = card.querySelector(`[data-sp-mode="${CSS.escape(spId)}"]`);
        const memBox = card.querySelector(`[data-sp-members-box="${CSS.escape(spId)}"]`);
        const upgWrap = card.querySelector(`[data-sp-upgrade-wrap="${CSS.escape(spId)}"]`);
        const upgChk = card.querySelector(`[data-sp-upgrade-chk="${CSS.escape(spId)}"]`);
        if (!upgWrap || !memBox) return;
        const isDocker = !modeSel || modeSel.value === "docker";
        const needsUpgrade =
          isDocker &&
          [...memBox.querySelectorAll('input[type="checkbox"]:checked')].some((c) => {
            const m = c.dataset.maxMode || "write_files";
            return m === "write_files" || m === "read_only";
          });
        const wasHidden = upgWrap.classList.contains("hidden");
        upgWrap.classList.toggle("hidden", !needsUpgrade);
        if (needsUpgrade && wasHidden && upgChk) upgChk.checked = true;
      });

      els.sharedProjectsAdminList.addEventListener("click", async (e) => {
        const copyBtn = e.target.closest("[data-copy-sp-path]");
        if (copyBtn) {
          const pathText = copyBtn.dataset.copySpPath || "";
          if (pathText) {
            try {
              await navigator.clipboard.writeText(pathText);
              showToast("Путь к папке скопирован");
            } catch {
              showToast(pathText);
            }
          }
          return;
        }

        const openBtn = e.target.closest("[data-open-sp]");
        if (openBtn) {
          const spName = openBtn.dataset.openSp;
          els.usersAdminModal.classList.add("hidden");
          state.activeTab = "project";
          localStorage.setItem("agy_hub_tab", "project");
          await loadProjects();
          await selectProjectFolder(spName);
          return;
        }

        const saveBtn = e.target.closest("[data-save-sp]");
        if (saveBtn) {
          const spId = saveBtn.dataset.saveSp;
          const card = els.sharedProjectsAdminList.querySelector(
            `[data-sp-card="${CSS.escape(spId)}"]`
          );
          if (!card) return;
          const modeSel = card.querySelector(`[data-sp-mode="${CSS.escape(spId)}"]`);
          const execMode = modeSel ? modeSel.value : "docker";
          const storSel = card.querySelector(`[data-sp-storage="${CSS.escape(spId)}"]`);
          const storageLoc =
            storSel && storSel.value === "projects_root" ? "projects_root" : "shared_dir";
          const descInp = card.querySelector(`[data-sp-desc="${CSS.escape(spId)}"]`);
          const description = descInp ? descInp.value.trim() : undefined;
          const memBox = card.querySelector(`[data-sp-members-box="${CSS.escape(spId)}"]`);
          const memberIds = memBox
            ? [...memBox.querySelectorAll('input[type="checkbox"]:checked')].map((c) => c.value)
            : [];
          const upgWrap = card.querySelector(`[data-sp-upgrade-wrap="${CSS.escape(spId)}"]`);
          const upgChk = card.querySelector(`[data-sp-upgrade-chk="${CSS.escape(spId)}"]`);
          const upgradeMembersDocker = Boolean(
            execMode === "docker" &&
            upgWrap &&
            !upgWrap.classList.contains("hidden") &&
            upgChk &&
            upgChk.checked
          );
          try {
            const patchBody = {
              execution_mode: execMode,
              storage_location: storageLoc,
              member_ids: memberIds,
              upgrade_members_docker: upgradeMembersDocker,
            };
            if (description !== undefined) {
              patchBody.description = description;
            }
            await apiFetch(`/api/admin/shared-projects/${encodeURIComponent(spId)}`, {
              method: "PATCH",
              body: JSON.stringify(patchBody),
            });
            showToast("Настройки общего проекта обновлены");
            await Promise.all([loadAdminOverview(), loadProjects()]);
          } catch (err) {
            showToast(`Ошибка: ${err.message}`);
          }
          return;
        }

        const delBtn = e.target.closest("[data-del-sp]");
        if (delBtn) {
          const spId = delBtn.dataset.delSp;
          const spName = delBtn.dataset.delSpName || spId;
          const ok = await askUserConfirm({
            title: "Отключение общего доступа",
            message: `Убрать проект «${spName}» из списка общих проектов? (Сама папка с кодом на диске не удаляется.)`,
            confirmText: "Убрать",
            danger: true,
          });
          if (!ok) {
            return;
          }
          try {
            await apiFetch(`/api/admin/shared-projects/${encodeURIComponent(spId)}`, {
              method: "DELETE",
            });
            showToast(`Общий проект «${spName}» убран из общего доступа`);
            await Promise.all([loadAdminOverview(), loadProjects()]);
          } catch (err) {
            showToast(`Ошибка: ${err.message}`);
          }
        }
      });
    }

